function CelebrationGraphicView({ type, loopAnim, spinAnim, glowAnim }) {
  if (type === 'bowled') return <BowledGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'caught') return <CaughtGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'lbw') return <LbwGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'run_out' || type === 'stumped') return <RunOutGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'six_stadium') return <SixStadiumGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'six_helicopter') return <SixHelicopterGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'six_straight') return <SixStraightGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'six_ramp') return <SixRampGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'six') return <SixStadiumGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'four_drive') return <FourDriveGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'four_pull') return <FourPullGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'four_cut') return <FourCutGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  if (type === 'four') return <FourDriveGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
  return <BowledGraphic loopAnim={loopAnim} spinAnim={spinAnim} glowAnim={glowAnim} />;
}

