  const handleEmailSubmit = () => {
    setAuthError('');
    const cleanEmail = authEmail.trim().toLowerCase();
    if (!cleanEmail) {
      setAuthError('Please enter your email address');
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(cleanEmail)) {
      setAuthError('Please enter a valid email address (e.g. player@cricketadda.com)');
      return;
    }

    setAuthLoading(true);

    // Generate authentic 6-digit OTP verification code
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);

    // Check if email already exists in users database
    const existing = usersDb.find(u => u.email && u.email.toLowerCase() === cleanEmail);
    const isOldUser = Boolean(existing);
    setIsExistingUser(isOldUser);

    // Dispatch real email verification to recipient's email
    sendVerificationOtpEmail(cleanEmail, newOtp).catch(() => {});

    setTimeout(() => {
      setAuthLoading(false);
      setAuthStep(2);
      setAuthOtpTimer(600);
      setAuthOtp(['', '', '', '', '', '']);
      showAppToast(`Verification code sent to ${cleanEmail}!`, '📨');
    }, 400);
  };

