                  {dismissalType === 'caught' && `c ${customWicketFielder.trim() || wicketFielder} b ${bowler}`}
                  {dismissalType === 'bowled' && `b ${bowler}`}
                  {dismissalType === 'lbw' && `lbw b ${bowler}`}
                  {dismissalType === 'run_out' && `run out (${customWicketFielder.trim() || wicketFielder})`}
                  {dismissalType === 'stumped' && `st ${customWicketFielder.trim() || wicketFielder} b ${bowler}`}
                  {dismissalType === 'hit_wicket' && `hit wicket b ${bowler}`}
                  {dismissalType === 'obstructing' && `obstructing the field`}
                  {dismissalType === 'retired' && `retired out`}
