                <TouchableOpacity style={[styles.confirmBtn, { backgroundColor: '#d97706' }]} onPress={confirmDropCatch}>
                  <Text style={[styles.confirmBtnText, { color: '#ffffff' }]}>Confirm Dropped Catch 🧤</Text>
                </TouchableOpacity>
